import {MongoClient} from "mongodb";

const uri=process.env.MONGODB_URI;
const dbName=process.env.MONGODB_DB||"order_service";
if(!uri) throw new Error("MONGODB_URI is required");

export const client=new MongoClient(uri);
export const db=client.db(dbName);

export async function connectDatabase(){
  await client.connect();
  const orders=db.collection("orders");
  const products=db.collection("products");
  const inventory=db.collection("inventory");
  const audit=db.collection("orderAudit");
  await products.createIndex({sku:1},{unique:true});
  await inventory.createIndex({sku:1},{unique:true});
  await orders.createIndex({idempotencyKey:1},{unique:true});
  await orders.createIndex({customerId:1,createdAt:-1});
  await audit.createIndex({eventToken:1},{unique:true});
  return {orders,products,inventory,audit};
}
export async function closeDatabase(){await client.close();}

