import express from "express";
import {ObjectId} from "mongodb";
import {client,connectDatabase,closeDatabase,db} from "./db.js";

const app=express();
app.use(express.json());

const {orders,products,inventory,audit}=await connectDatabase();

app.get("/health",async(_req,res)=>{
  try{await db.command({ping:1});res.json({ok:true});}
  catch(e){console.error(e);res.status(503).json({ok:false});}
});

app.get("/products",async(_req,res)=>{
  const docs=await products.find({},{projection:{_id:0}}).sort({sku:1}).toArray();
  res.json(docs);
});

app.post("/orders",async(req,res)=>{
  const {customerId,items,idempotencyKey}=req.body;
  if(typeof customerId!=="string"||!Array.isArray(items)||items.length===0||
     typeof idempotencyKey!=="string"||!idempotencyKey){
    return res.status(400).json({error:"customerId, items and idempotencyKey are required"});
  }
  for(const item of items){
    if(typeof item?.sku!=="string"||!Number.isInteger(item?.quantity)||item.quantity<=0)
      return res.status(400).json({error:"Each item requires a positive integer quantity and string sku"});
  }

  const session=client.startSession();
  try{
    let resultOrder;
    let created = false;
    await session.withTransaction(async()=>{
      const existing=await orders.findOne({idempotencyKey},{session});
      if(existing){resultOrder=existing;return;}

      const skus=[...new Set(items.map(x=>x.sku))];
      const productDocs=await products.find({sku:{$in:skus}},{session}).toArray();
      const prices=new Map(productDocs.map(p=>[p.sku,p.price]));
      if(prices.size!==skus.length) throw new Error("One or more SKUs do not exist");

      const lines=items.map(x=>({sku:x.sku,quantity:x.quantity,unitPrice:prices.get(x.sku)}));
      const total=lines.reduce((sum,x)=>sum+x.unitPrice*x.quantity,0);

      for(const line of lines){
        const r=await inventory.updateOne(
          {sku:line.sku,stock:{$gte:line.quantity}},
          {$inc:{stock:-line.quantity}},
          {session}
        );
        if(r.matchedCount!==1) throw new Error("Insufficient inventory for "+line.sku);
      }

      const order={customerId,items:lines,total,status:"paid",idempotencyKey,createdAt:new Date()};
      const inserted=await orders.insertOne(order,{session});
      resultOrder={_id:inserted.insertedId,...order};
      created = true;
    });
    res.status(created ? 201 : 200).json(resultOrder);
  }catch(e){
    if(e?.code===11000){
      const existing=await orders.findOne({idempotencyKey});
      return res.status(200).json(existing);
    }
    if(/Insufficient inventory|SKUs do not exist/.test(e.message))
      return res.status(409).json({error:e.message});
    console.error(e);
    res.status(500).json({error:"internal error"});
  }finally{await session.endSession();}
});

app.get("/orders/:id",async(req,res)=>{
  let id;
  try{id=new ObjectId(req.params.id);}catch{return res.status(400).json({error:"invalid order id"});}
  const order=await orders.findOne({_id:id});
  if(!order)return res.status(404).json({error:"Order not found"});
  res.json(order);
});

const server=app.listen(process.env.PORT||3000,()=>console.log("Order service listening on port "+(process.env.PORT||3000)));

const changeStream=orders.watch();
changeStream.on("change",async change=>{
  try{
    await audit.updateOne(
      {eventToken:change._id},
      {$setOnInsert:{eventToken:change._id,operationType:change.operationType,documentKey:change.documentKey,observedAt:new Date()}},
      {upsert:true}
    );
  }catch(e){console.error("audit change stream error",e);}
});

async function shutdown(){
  await changeStream.close();
  server.close(async()=>{await closeDatabase();process.exit(0);});
}
process.on("SIGINT",shutdown);
process.on("SIGTERM",shutdown);
